INSERT OR REPLACE INTO resources (id, category, name, description, address, phone, website, hours, notes, sort_order, is_active, created_at, updated_at) VALUES ('40e3c3cf-8d10-5a2a-b9e1-756d96de7954', 'domestic-violence', 'Greater Richmond Regional Hotline (YWCA)', '24/7 confidential crisis line for domestic and sexual violence - serving Richmond, Henrico, and Chesterfield. Managed by YWCA, routes callers to Safe Harbor and other partners for emergency shelter, safety planning, and counseling.', 'Serving Richmond & Henrico', '(804) 612-6126', 'https://ywcarichmond.org/get-help/', '24 hours, 7 days a week', 'If you are in immediate danger, call 911 first. Text-capable line.', 48, 1, '2026-02-01T00:00:00Z', '2026-02-01T00:00:00Z');
INSERT OR REPLACE INTO resources (id, category, name, description, address, phone, website, hours, notes, sort_order, is_active, created_at, updated_at) VALUES ('08223f1f-f930-5d8f-96af-ac3a48e2b196', 'domestic-violence', 'YWCA of Richmond - Domestic Violence Services', 'Emergency shelter, crisis counseling, court advocacy, and support groups for survivors of domestic and sexual violence.', '6 N. Fifth St, Richmond, VA 23219', '(804) 643-6761', 'https://ywcarichmond.org/what-we-do/', 'Admin Mon–Fri 9am–5pm; crisis line 24/7 at 804-612-6126', 'Services are free and confidential.', 49, 1, '2026-02-01T00:00:00Z', '2026-02-01T00:00:00Z');
INSERT OR REPLACE INTO resources (id, category, name, description, address, phone, website, hours, notes, sort_order, is_active, created_at, updated_at) VALUES ('21003ccb-b8c8-58e2-a46b-3ac0eea3e136', 'domestic-violence', 'Safe Harbor - 24/7 Helpline', '24-hour crisis hotline for domestic and sexual violence survivors in Henrico County and Richmond. Access to emergency shelter, safety planning, and advocacy.', 'Serving Henrico & Richmond', '(804) 500-2755', 'https://safeharborshelter.com/', '24 hours, 7 days a week', 'Confidential - shelter location is not disclosed publicly for safety.', 50, 1, '2026-02-01T00:00:00Z', '2026-02-01T00:00:00Z');
INSERT OR REPLACE INTO resources (id, category, name, description, address, phone, website, hours, notes, sort_order, is_active, created_at, updated_at) VALUES ('1d2a59ac-6333-5f65-a4e9-7cc38175ce1b', 'domestic-violence', 'Safe Harbor - Administrative & Counseling Office', 'Non-crisis appointments, counseling, court advocacy, and prevention education.', '1934 N. Parham Rd, Suite 300, Henrico, VA 23229', '(804) 249-9470', 'https://safeharborshelter.com/contact/', 'Mon–Fri, business hours', 'For 24-hour crisis, call 804-500-2755.', 51, 1, '2026-02-01T00:00:00Z', '2026-02-01T00:00:00Z');
INSERT OR REPLACE INTO resources (id, category, name, description, address, phone, website, hours, notes, sort_order, is_active, created_at, updated_at) VALUES ('280698f8-c3ea-58eb-9b52-2f24ff096161', 'domestic-violence', 'Henrico Police - Domestic Violence Victim Services', 'Confidential support, safety planning, and criminal-justice advocacy for Henrico County domestic violence victims. Assistance with protective orders.', '7721 E. Parham Rd, Henrico, VA 23294', '(804) 501-4830', 'https://henrico.gov/police/crime-prevention/domestic-violence-assistance/', 'Mon–Fri 8am–4:30pm', 'Call 911 if in immediate danger.', 52, 1, '2026-02-01T00:00:00Z', '2026-02-01T00:00:00Z');
INSERT OR REPLACE INTO resources (id, category, name, description, address, phone, website, hours, notes, sort_order, is_active, created_at, updated_at) VALUES ('e5efe1b8-cd55-5a9b-9319-cd7bd9e31a43', 'domestic-violence', 'Richmond Police - Family & Sexual Violence Unit', 'Specialized investigators for domestic and sexual violence within Richmond City. Coordinates with victim advocates and shelters.', '200 W Grace St, Richmond, VA 23220', '(804) 646-3011', 'https://www.rva.gov/police', '24/7 dispatch - call 911 for emergencies', 'Non-emergency: dial 3-1-1 within Richmond.', 53, 1, '2026-02-01T00:00:00Z', '2026-02-01T00:00:00Z');
INSERT OR REPLACE INTO resources (id, category, name, description, address, phone, website, hours, notes, sort_order, is_active, created_at, updated_at) VALUES ('9967683e-fdd4-5c18-bbb1-22d5e4c6b07a', 'domestic-violence', 'Virginia Statewide Hotline (Action Alliance)', 'Statewide bilingual hotline (English/Spanish) for domestic and sexual violence - free, confidential, 24/7. Text and chat options available.', 'Statewide', '1 (800) 838-8238', 'https://vadata.org/', '24/7', 'Text: 804-793-9999. Chat at vadata.org.', 54, 1, '2026-02-01T00:00:00Z', '2026-02-01T00:00:00Z');
INSERT OR REPLACE INTO resources (id, category, name, description, address, phone, website, hours, notes, sort_order, is_active, created_at, updated_at) VALUES ('e6f2c5cd-796e-5703-8caa-1437fdecaa9c', 'domestic-violence', 'National Domestic Violence Hotline', '24/7 confidential support in 200+ languages. Text, call, or chat with trained advocates for safety planning and referrals.', 'Nationwide', '1 (800) 799-7233', 'https://www.thehotline.org/', '24/7', 'Text START to 88788. Deaf/hard of hearing: video call via thehotline.org.', 55, 1, '2026-02-01T00:00:00Z', '2026-02-01T00:00:00Z');
INSERT OR REPLACE INTO resources (id, category, name, description, address, phone, website, hours, notes, sort_order, is_active, created_at, updated_at) VALUES ('a755c6cd-a48c-58a7-b882-a896a51cc6be', 'domestic-violence', 'Central Virginia Legal Aid Society - Protective Orders', 'Free civil legal help for survivors of domestic violence - protective orders, custody, divorce, and eviction defense.', '101 W Broad St, Richmond, VA 23220', '(804) 648-1012', 'https://cvlas.org/', 'Mon–Fri 9am–5pm', 'Intake by phone - ask for the domestic violence advocate.', 56, 1, '2026-02-01T00:00:00Z', '2026-02-01T00:00:00Z');
INSERT OR REPLACE INTO resources (id, category, name, description, address, phone, website, hours, notes, sort_order, is_active, created_at, updated_at) VALUES ('bac61f7b-e41c-597f-a0c8-7e9f73e6910e', 'domestic-violence', 'Richmond SPCA - Safer Together (SAAF) Program', 'Free foster care for pets of domestic violence survivors entering shelter - so no one has to choose between safety and their beloved companion.', '2519 Hermitage Rd, Richmond, VA 23220', '(804) 521-1330', 'https://richmondspca.org/saaf-providing-a-safe-harbor-for-family-pets-at-a-time-of-critical-need/', 'Mon–Sun, by referral through YWCA/Safe Harbor', 'Confidential - coordinated via 804-612-6126.', 57, 1, '2026-02-01T00:00:00Z', '2026-02-01T00:00:00Z');
